-- Swarnim CSC service catalog and official portal directory.
-- Idempotent: safe to apply where these tables already exist.
create table if not exists public.swarnim_csc_services (
  id bigint generated by default as identity primary key,
  service_name text not null,
  category text not null,
  description text not null default '',
  portal_url text,
  login_required boolean not null default false,
  authorization_required boolean not null default false,
  availability_note text not null default 'राज्य, विभाग, सेवा प्रदाता और ऑपरेटर की अनुमति के अनुसार उपलब्धता बदल सकती है।',
  is_active boolean not null default true,
  sort_order integer not null default 100,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint swarnim_csc_services_name_category_unique unique (service_name, category)
);
create table if not exists public.swarnim_csc_portals (
  id bigint generated by default as identity primary key,
  portal_name text not null,
  service_category text not null,
  portal_url text not null,
  login_url text,
  official_owner text,
  access_type text not null default 'public_portal' check (access_type in ('login','public_portal','registration','service_directory')),
  jurisdiction text not null default 'central' check (jurisdiction in ('central','state','district','private_authorized')),
  state_name text,
  official_domain_verified boolean not null default false,
  verification_note text,
  is_active boolean not null default true,
  sort_order integer not null default 100,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint swarnim_csc_portals_url_unique unique (portal_url)
);

alter table public.swarnim_csc_services enable row level security;
alter table public.swarnim_csc_portals enable row level security;

drop policy if exists swarnim_csc_services_public_read_active on public.swarnim_csc_services;
create policy swarnim_csc_services_public_read_active on public.swarnim_csc_services
  for select to anon, authenticated using (is_active = true);
drop policy if exists swarnim_csc_services_admin_all on public.swarnim_csc_services;
create policy swarnim_csc_services_admin_all on public.swarnim_csc_services
  for all to authenticated using ((select is_admin())) with check ((select is_admin()));

drop policy if exists swarnim_csc_portals_public_read_active on public.swarnim_csc_portals;
create policy swarnim_csc_portals_public_read_active on public.swarnim_csc_portals
  for select to anon, authenticated using (is_active = true);
drop policy if exists swarnim_csc_portals_admin_all on public.swarnim_csc_portals;
create policy swarnim_csc_portals_admin_all on public.swarnim_csc_portals
  for all to authenticated using ((select is_admin())) with check ((select is_admin()));

grant select on public.swarnim_csc_services, public.swarnim_csc_portals to anon, authenticated;
grant insert, update, delete on public.swarnim_csc_services, public.swarnim_csc_portals to authenticated;
grant usage, select on sequence public.swarnim_csc_services_id_seq, public.swarnim_csc_portals_id_seq to authenticated;

insert into public.swarnim_csc_services
(service_name,category,description,portal_url,login_required,authorization_required,availability_note,sort_order)
values
('सरकारी प्रमाणपत्र आवेदन','सरकारी दस्तावेज़','आय, जाति, निवास, जन्म/मृत्यु, डोमिसाइल तथा राज्य-विशिष्ट प्रमाणपत्रों के आवेदन/स्थिति में सहायता।','https://serviceonline.gov.in/',true,false,'सेवा राज्य/जिले के अनुसार अलग हो सकती है; मूल आवेदन संबंधित सरकारी पोर्टल पर होगा।',10),
('आधार सेवाओं की जानकारी/सहायता','पहचान दस्तावेज़','आधार संबंधी आधिकारिक सेवाओं तक मार्गदर्शन; बायोमेट्रिक सेवा केवल अधिकृत केंद्र पर।','https://myaadhaar.uidai.gov.in/',true,true,'आधार नामांकन/अपडेट के लिए UIDAI द्वारा अधिकृत केंद्र और प्रक्रिया आवश्यक है।',20),
('PAN कार्ड आवेदन/सुधार सहायता','पहचान दस्तावेज़','PAN आवेदन, सुधार और स्थिति जाँच के लिए अधिकृत पोर्टल तक सहायता।','https://digitalseva.csc.gov.in/',true,true,'CSC के भीतर संबंधित सेवा सक्रिय और ऑपरेटर अधिकृत होने पर ही प्रक्रिया करें।',30),
('DigiLocker दस्तावेज़','डिजिटल दस्तावेज़','डिजिटल दस्तावेज़ खाता खोलने और जारी दस्तावेज़ प्राप्त करने में सहायता।','https://www.digilocker.gov.in/',true,false,'नागरिक का OTP/पासवर्ड स्वयं SBPF ऑपरेटर द्वारा संग्रहित न किया जाए।',40),
('सरकारी योजनाएँ एवं लाभ','सरकारी योजनाएँ','केंद्र/राज्य योजनाओं की जानकारी, पात्रता, आवश्यक दस्तावेज़ और आवेदन लिंक।','https://services.india.gov.in/',false,false,'पात्रता और लाभ संबंधित विभाग की आधिकारिक शर्तों से सत्यापित करें।',50),
('बैंकिंग/AEPS/DigiPay','वित्तीय सेवाएँ','बैंकिंग प्रतिनिधि सेवाएँ, बैलेंस/निकासी आदि केवल संबंधित अधिकृत बैंक BC/VLE व्यवस्था के माध्यम से।','https://digitalseva.csc.gov.in/',true,true,'बैंक BC, AEPS, DigiPay और बायोमेट्रिक लेनदेन के लिए वैध अनुमति/डिवाइस अनिवार्य।',60),
('लोन आवेदन सहायता','वित्तीय सेवाएँ','मुद्रा, KCC, PM SVANidhi और अन्य बैंक/सरकारी ऋण योजनाओं की जानकारी व आधिकारिक आवेदन लिंक।','https://www.mudra.org.in/',true,false,'लोन मंजूरी बैंक/ऋणदाता करता है; SBPF किसी लोन की गारंटी नहीं देगा और OTP/PIN नहीं लेगा।',70),
('बीमा एवं पेंशन','वित्तीय सेवाएँ','उपलब्ध योजनाओं के अनुसार बीमा, APY/NPS, पेंशन और Jeevan Pramaan संबंधी सहायता।','https://digitalseva.csc.gov.in/',true,true,'बीमा/पेंशन वितरण के लिए संबंधित अधिकृत एजेंट/ऑपरेटर की अनुमति आवश्यक हो सकती है।',80),
('बिजली/पानी/गैस बिल भुगतान','बिल भुगतान','बिजली, पानी, गैस तथा अन्य उपयोगिता बिल भुगतान की सुविधा के आधिकारिक लिंक।','https://digitalseva.csc.gov.in/',true,true,'CSC BBPS या संबंधित भुगतान प्रदाता में सेवा उपलब्ध होने पर ही भुगतान करें; रसीद दें।',90),
('मोबाइल/DTH रिचार्ज','बिल भुगतान','मोबाइल, डेटा कार्ड और DTH रिचार्ज/बिल भुगतान।','https://digitalseva.csc.gov.in/',true,true,'ऑपरेटर/सेवा प्रदाता की सक्रिय सुविधा आवश्यक; सफल भुगतान की रसीद दें।',100),
('छात्रवृत्ति/प्रवेश/परीक्षा फॉर्म','शिक्षा','छात्रवृत्ति, NIOS, प्रवेश, प्रतियोगी परीक्षा और सरकारी परीक्षा आवेदन में सहायता।','https://services.india.gov.in/',false,false,'आवेदन की अंतिम तिथि, शुल्क और पात्रता आधिकारिक सूचना से जाँचें।',110),
('नौकरी/रोजगार आवेदन','रोजगार','रोजगार पंजीकरण, सरकारी नौकरी आवेदन और National Career Service तक सहायता।','https://www.ncs.gov.in/',true,false,'नौकरी दिलाने की गारंटी न दें; आवेदन शुल्क केवल आधिकारिक पोर्टल पर।',120),
('स्वास्थ्य/आयुष्मान/टेलीमेडिसिन','स्वास्थ्य','आयुष्मान भारत पात्रता/लाभार्थी सहायता और उपलब्ध टेलीमेडिसिन सेवाओं का मार्गदर्शन।','https://beneficiary.nha.gov.in/',true,true,'लाभार्थी लॉगिन/स्वास्थ्य डेटा गोपनीय रखें; केवल अधिकृत स्वास्थ्य सेवाएँ प्रदान करें।',130),
('किसान/कृषि सेवाएँ','कृषि','PM-KISAN, KCC, फसल बीमा, किसान पेंशन और कृषि सलाह से जुड़ी आवेदन सहायता।','https://pmkisan.gov.in/',true,false,'योजना/कृषि सेवा की उपलब्धता राज्य, पात्रता और अधिकृत पोर्टल पर निर्भर है।',140),
('पासपोर्ट आवेदन सहायता','यात्रा एवं परिवहन','पासपोर्ट आवेदन और अपॉइंटमेंट संबंधी आधिकारिक प्रक्रिया में सहायता।','https://www.passportindia.gov.in/',true,false,'आवेदन/अपॉइंटमेंट अंतिम रूप से आधिकारिक Passport Seva पोर्टल पर।',150),
('रेल/बस/हवाई टिकट','यात्रा एवं परिवहन','यात्रा टिकट बुकिंग और संबंधित सहायता।','https://digitalseva.csc.gov.in/',true,true,'रेल टिकट केवल IRCTC-अधिकृत एजेंट व्यवस्था से; सेवा/कमीशन नियम लागू होंगे।',160),
('व्यापार पंजीकरण/कर सहायता','व्यवसाय','Udyam/MSME, GST, FSSAI, ITR और डिजिटल सिग्नेचर से जुड़ी आवेदन सहायता।','https://services.india.gov.in/',true,false,'कानूनी/कर सलाह विशेषज्ञ का विकल्प नहीं; लाइसेंस-आधारित सेवाओं में अनुमति जाँचें।',170),
('शिकायत एवं जनसुनवाई','नागरिक सहायता','सरकारी शिकायत पोर्टल, शिकायत संख्या, स्थिति ट्रैकिंग और संबंधित विभाग तक मार्गदर्शन।','https://services.india.gov.in/',false,false,'नागरिक की सहमति से ही शिकायत विवरण दर्ज करें; निजी दस्तावेज़ सार्वजनिक न हों।',180),
